+import { writeHermesConfig, type HermesConfig } from "./index.js";
+
+describe("writeHermesConfig", () => {
+  let hermesHome: string;
+
+  beforeEach(() => {
+    hermesHome = join(tmpdir(), `hermes-config-test-${Date.now()}`);
+    mkdirSync(hermesHome, { recursive: true });
+  });
+
+  afterEach(() => {
+    rmSync(hermesHome, { recursive: true, force: true });
+  });
+
+  it("produces valid YAML with model stanza", () => {
+    const config: HermesConfig = {
+      provider: "deepseek",
+      model: "deepseek-v4-flash",
+    };
+    writeHermesConfig(hermesHome, config);
+
+    const raw = readFileSync(join(hermesHome, "config.yaml"), "utf-8");
+    const parsed = parseYaml(raw) as Record<string, unknown>;
+
+    expect(parsed).toBeDefined();
+    const model = parsed.model as Record<string, string>;
+    expect(model.provider).toBe("deepseek");
+    expect(model.default).toBe("deepseek-v4-flash");
+  });
+
+  it("includes MCP stanza when RAG_MCP_URL is set", () => {
+    const config: HermesConfig = {
+      provider: "openai",
+      model: "gpt-4o",
+      ragMcpUrl: "http://rag-server:4000/mcp",
+      ragMcpToken: "secret-token",
+    };
+    writeHermesConfig(hermesHome, config);
+
+    const raw = readFileSync(join(hermesHome, "config.yaml"), "utf-8");
+    const parsed = parseYaml(raw) as Record<string, unknown>;
+
+    expect(parsed.mcp_servers).toBeDefined();
+    const mcpServers = parsed.mcp_servers as Record<string, unknown>;
+    const rag = mcpServers.rag as Record<string, unknown>;
+    expect(rag.url).toBe("http://rag-server:4000/mcp");
+    const headers = rag.headers as Record<string, string>;
+    expect(headers.Authorization).toBe("Bearer secret-token");
+  });
+
+  it("omits MCP stanza when RAG_MCP_URL is not set", () => {
+    const config: HermesConfig = {
+      provider: "openai",
+      model: "gpt-4o",
+    };
+    writeHermesConfig(hermesHome, config);
+
+    const raw = readFileSync(join(hermesHome, "config.yaml"), "utf-8");
+    const parsed = parseYaml(raw) as Record<string, unknown>;
+
+    expect(parsed.mcp_servers).toBeUndefined();
+  });
+
+  it("includes MCP stanza without Authorization header when no token", () => {
+    const config: HermesConfig = {
+      provider: "openai",
+      model: "gpt-4o",
+      ragMcpUrl: "http://rag-server:4000/mcp",
+    };
+    writeHermesConfig(hermesHome, config);
+
+    const raw = readFileSync(join(hermesHome, "config.yaml"), "utf-8");
+    const parsed = parseYaml(raw) as Record<string, unknown>;
+
+    const mcpServers = parsed.mcp_servers as Record<string, unknown>;
+    const rag = mcpServers.rag as Record<string, unknown>;
+    expect(rag.url).toBe("http://rag-server:4000/mcp");
+    expect(rag.headers).toBeUndefined();
+  });
+
+  it("creates hermesHome directory if it does not exist", () => {
+    const newDir = join(hermesHome, "nested", "dir");
+    writeHermesConfig(newDir, { provider: "openai", model: "gpt-4o" });
+
+    const raw = readFileSync(join(newDir, "config.yaml"), "utf-8");
+    expect(raw).toContain("openai");
+  });
+
+  it("does not include a memory stanza (stateless by default)", () => {
