@@ -0,0 +1,14 @@
+import { writeFileSync, unlinkSync, existsSync } from "node:fs";
+import { join } from "node:path";
+
+export function resolveSSHKey(
+  env: { SSH_PRIVATE_KEY?: string },
+  executorWorkdir: string,
+): { sshKeyPath: string | undefined } {
+  if (!env.SSH_PRIVATE_KEY) return { sshKeyPath: undefined };
+  const keyPath = join(executorWorkdir, "ssh_key");
+  if (existsSync(keyPath)) unlinkSync(keyPath);
+  const pem = env.SSH_PRIVATE_KEY.replace(/\\n/g, "\n");
+  writeFileSync(keyPath, pem, { mode: 0o400 });
+  return { sshKeyPath: keyPath };
+}
